function generateKey(num1, num2, num3) {
  let key = 0;
  for (let place = 1000; place >= 1; place /= 10) {
    const d1 = Math.floor(num1 / place) % 10;
    const d2 = Math.floor(num2 / place) % 10;
    const d3 = Math.floor(num3 / place) % 10;
    key = key * 10 + Math.min(d1, d2, d3);
  }
  return key;
}

