function generateKey(num1, num2, num3) {
  // Pad the decimal strings to four characters and compare them character by character.
  const [a, b, c] = [num1, num2, num3].map(x => String(x).padStart(4, '0'));
  let key = '';
  for (let i = 0; i < 4; i++) key += String(Math.min(Number(a[i]), Number(b[i]), Number(c[i])));
  return parseInt(key, 10);
}

