function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  // Small inputs mix lengths from one to four digits; large ones always use four digits.
  const number = () => {
    const digits = size === 'large' ? 4 : 1 + pick(4);
    const low = 10 ** (digits - 1);
    return low + pick(9 * low);
  };
  return [number(), number(), number()];
}
